solution.javascript:
function buildTree(preorder, inorder) {
  const inMap = {}; inorder.forEach((v, i) => inMap[v] = i);
  function build(preStart, preEnd, inStart, inEnd) {
    if (preStart > preEnd) return null;
    const root = new TreeNode(preorder[preStart]);
    const mid = inMap[root.val];
    const leftSize = mid - inStart;
    root.left = build(preStart + 1, preStart + leftSize, inStart, mid - 1);
    root.right = build(preStart + leftSize + 1, preEnd, mid + 1, inEnd);
    return root;
  }
  return build(0, preorder.length - 1, 0, inorder.length - 1);
}

solution.cpp:
TreeNode* buildTree(vector<int>& preorder, vector<int>& inorder) {
    unordered_map<int,int> inMap;
    for (int i = 0; i < inorder.size(); i++) inMap[inorder[i]] = i;
    function<TreeNode*(int,int,int,int)> build = [&](int ps, int pe, int is, int ie) {
        if (ps > pe) return (TreeNode*)nullptr;
        TreeNode* root = new TreeNode(preorder[ps]);
        int mid = inMap[root->val];
        int leftSize = mid - is;
        root->left = build(ps + 1, ps + leftSize, is, mid - 1);
        root->right = build(ps + leftSize + 1, pe, mid + 1, ie);
        return root;
    };
    return build(0, preorder.size() - 1, 0, inorder.size() - 1);
}
